const input = $input.first().json;
const body = input.body || input;

if (!body.event_id || !body.event_type) {
  return [{ json: { isHighRisk: false, error: 'Invalid event payload' } }];
}

const suspiciousVoice = body.voice_authenticity === 'SUSPICIOUS' || body.voice_authenticity === 'FAKE';
const speakerFailed = body.speaker_match === false;
const invalidChallenge = body.challenge_valid === false;
const isHighRisk = body.risk_level === 'HIGH' || suspiciousVoice || speakerFailed || invalidChallenge;

const triggers = [];
if (suspiciousVoice) triggers.push('SUSPICIOUS_VOICE_AUTHENTICITY');
if (speakerFailed) triggers.push('SPEAKER_VERIFICATION_FAILED');
if (invalidChallenge) triggers.push('INVALID_CHALLENGE_PHRASE');

return [{
  json: {
    isHighRisk,
    severity: suspiciousVoice ? 'CRITICAL' : 'HIGH',
    triggers,
    event_id: body.event_id,
    session_id: body.session_id,
    industry: body.industry,
    action: body.action,
    decision: body.decision,
    timestamp: body.timestamp
  }
}];

const ev = $input.first().json;
return [{
  json: {
    status: 'high_risk_incident_recorded',
    recipient: 'security-admin@voicesuraksha.local',
    severity: ev.severity,
    incident_summary: `High-risk voice attempt in ${ev.industry} (${ev.action}). Triggers: ${ev.triggers.join(', ')}. FastAPI Decision: ${ev.decision}.`,
    event_id: ev.event_id,
    recorded_at: new Date().toISOString()
  }
}];
